mapper.insert:
INSERT INTO balance_adjustments (
	user_num, account_num, adjustment_amount, adjustment_date
)
VALUES (
	#{userNum}, #{accountNum}, #{adjustmentAmount}, #{adjustmentDate}
)

mapper.select:
SELECT j.adjustment_num, j.account_num, a.account_name,
		j.adjustment_amount, j.adjustment_date
FROM balance_adjustments j
JOIN accounts a ON j.account_num = a.account_num
WHERE j.user_num = #{userNum}
  AND j.use_yn = 'Y'

  AND j.adjustment_date >= #{startDate}
  AND j.adjustment_date < #{endDate}

ORDER BY j.adjustment_date DESC, j.adjustment_num ASC
